# Generated by tools/convex-gen-test.R with reference values from tools/convex-probe.jl
# (ConvexOptimization.jl 0.1.4, SymbolicAnalysis.jl 0.5.8, Clarabel.jl 0.11.1 and
# MathOptInterface.jl 1.54.0); edit the generator, not this file.

cvx_cons <- function() list(ConeConstraint(function(u, p) u[1] + u[2] - 1, MOI$Zeros(1)),
                            ConeConstraint(function(u, p) c(u[1], u[2]), MOI$Nonnegatives(2)))
cvx_c1 <- function() list(ConeConstraint(function(u, p) u[1] + u[2] - 1, MOI$Zeros(1)))
cvx_lp_cons <- function() list(ConeConstraint(function(u, p) u[1] + u[2] - 1 - p[2], MOI$Zeros(1)),
                               ConeConstraint(function(u, p) c(u[1], u[2]), MOI$Nonnegatives(2)))
cvx_A <- matrix(c(1, 1), 2, 1)
cvx_b <- c(0, 2)
cvx_Al <- matrix(c(1, 0.2, 0.7, 0.5, 1, 0.7), 3, 2)
cvx_bl <- c(1, 2, 0.5)
cvx_alg <- ConvexMOI(ClarabelOptimizer)

test_that("LP solve: primal, objective, retcode and one dual per constraint", {
  cc <- c(1, 2)
  prob <- ConvexOptimizationProblem(function(u, p) cc[1] * u[1] + cc[2] * u[2], c(0.5, 0.5), constraints = cvx_cons())
  sol <- solve(prob, cvx_alg)
  expect_s3_class(sol, "OptimizationSolution")
  expect_true(successful_retcode(sol$retcode))
  expect_equal(sol$u, c(1, 0), tolerance = 1e-6)
  expect_equal(sol$objective, 1, tolerance = 1e-6)
  expect_length(sol$dual, 2L)
  expect_equal(sol$dual[[1]], 1, tolerance = 1e-6)
  expect_equal(sol$dual[[2]], c(0, 1), tolerance = 1e-6)
  expect_s3_class(sol$cache, "AbstractOptimizationCache")
  expect_s3_class(sol$cache$p, "NullParameters")
  expect_identical(sol$cache$u0, c(0.5, 0.5))
})

