  expect_warning(expect_error(solve(prob, cvx_alg), "not certified convex"), "multiple non-constant")
})

test_that("an SOC constraint lowers and solves", {
  cons <- list(ConeConstraint(function(u, p) c(u[1] - 3, u[2] - 4), MOI$Zeros(2)),
               ConeConstraint(function(u, p) c(u[3], u[1], u[2]), MOI$SecondOrderCone(3)))
  sol <- solve(ConvexOptimizationProblem(function(u, p) u[3], c(0, 0, 0), constraints = cons), cvx_alg)
  expect_true(successful_retcode(sol$retcode))
  expect_equal(sol$objective, 5, tolerance = 1e-5)
  expect_equal(sol$u[3], 5, tolerance = 1e-5)
})

test_that("a norm objective is lowered through its epigraph", {
  sol <- solve(ConvexOptimizationProblem(function(u, p) norm(cvx_A %*% u - cvx_b, "2"), 0), cvx_alg)
  expect_true(successful_retcode(sol$retcode))
  expect_length(sol$u, 1L)
  expect_equal(sol$u, 1, tolerance = 1e-6)
  expect_equal(sol$objective, sqrt(2), tolerance = 1e-6)
})

test_that("a norm objective with constraints keeps the duals 1:1 with the user constraints", {
