})

test_that("an invalid epigraph lowering is rejected, not silently solved", {
  f <- function(u, p) norm(cvx_A %*% u - cvx_b, "2")
  expect_error(solve(ConvexOptimizationProblem(f, 0, sense = "MaxSense"), cvx_alg), "through its epigraph")
  expect_error(solve(ConvexOptimizationProblem(function(u, p) -norm(cvx_A %*% u - cvx_b, "2"), 0), cvx_alg),
               "through its epigraph")
  expect_error(solve(ConvexOptimizationProblem(function(u, p) norm(cvx_A %*% u - cvx_b, 3), 0), cvx_alg),
               "got p = 3")
  # u^2 inside the norm is a nested atom whose sign can change, so the
  # certificate rejects it
  expect_error(solve(ConvexOptimizationProblem(function(u, p) norm(u^2 - 1, "2"), c(0.5, 0.5)), cvx_alg),
               "not certified convex")
})

test_that("l1 and linf norm objectives lower to their cones", {
  sol1 <- solve(ConvexOptimizationProblem(function(u, p) norm(u - 1, "1"), c(0.5, 0.5), constraints = cvx_c1()),
                cvx_alg)
  expect_true(successful_retcode(sol1$retcode))
  expect_equal(sol1$objective, 1, tolerance = 1e-6)
  expect_equal(sum(sol1$u), 1, tolerance = 1e-6)
  expect_length(sol1$dual, 1L)
  soli <- solve(ConvexOptimizationProblem(function(u, p) norm(u - 1, Inf), c(0.5, 0.5), constraints = cvx_c1()),
                cvx_alg)
  expect_true(successful_retcode(soli$retcode))
  expect_equal(soli$objective, 0.5, tolerance = 1e-6)
  expect_equal(soli$u, c(0.5, 0.5), tolerance = 1e-6)
  # the types of base::norm name the same vector norms
  solo <- solve(ConvexOptimizationProblem(function(u, p) norm(u - 1), c(0.5, 0.5), constraints = cvx_c1()), cvx_alg)
  expect_equal(solo$objective, 1, tolerance = 1e-6)
  solm <- solve(ConvexOptimizationProblem(function(u, p) norm(u - 1, "M"), c(0.5, 0.5), constraints = cvx_c1()),
                cvx_alg)
  expect_equal(solm$objective, 0.5, tolerance = 1e-6)
})

