cvx_lp_analytic <- function(th) {
  s <- 1 + th[2]
  if (th[1] < 1) list(u = c(s, 0), obj = th[1] * s, d1 = th[1], d2 = c(0, 1 - th[1]))
  else list(u = c(0, s), obj = s, d1 = 1, d2 = c(th[1] - 1, 0))
}
cvx_lp_sweep <- list(c(0.5, 0), c(2, 1), c(-1, 0.5), c(0, 3), c(0.5, 0))

test_that("parametric LP: reinit matches the analytic optimum and a cold solve", {
  prob <- ConvexOptimizationProblem(function(u, p) p[1] * u[1] + u[2], c(0.5, 0.5), c(0.5, 0),
                                    constraints = cvx_lp_cons())
  cache <- init(prob, cvx_alg)
  for (th in cvx_lp_sweep) {
    cache <- reinit(cache, p = th)
    sol <- solve_integrator(cache)
    an <- cvx_lp_analytic(th)
    expect_true(successful_retcode(sol$retcode))
    expect_equal(sol$u, an$u, tolerance = 1e-6)
    expect_equal(sol$objective, an$obj, tolerance = 1e-6)
    expect_equal(sol$dual[[1]], an$d1, tolerance = 1e-6)
    expect_equal(sol$dual[[2]], an$d2, tolerance = 1e-6)
    expect_identical(cache$p, th)
    cold <- solve(remake(prob, p = th), cvx_alg)
    expect_equal(sol$u, cold$u, tolerance = 1e-8)
    expect_equal(sol$objective, cold$objective, tolerance = 1e-8)
    expect_equal(sol$dual, cold$dual, tolerance = 1e-8)
    expect_identical(lengths(sol$dual), vapply(prob$constraints, function(con) MOI$dimension(con$set), 0L))
  }
})

test_that("re-solving at a new p does no symbolic work", {
  ntrace <- 0L
  prob <- ConvexOptimizationProblem(function(u, p) {
    ntrace <<- ntrace + 1L
    p[1] * u[1] + u[2]
  }, c(0.5, 0.5), c(0.5, 0), constraints = cvx_lp_cons())
  cache <- init(prob, cvx_alg)
  expect_identical(ntrace, 1L)
  dpp <- cache$dpp
  for (th in cvx_lp_sweep) {
    cache <- reinit(cache, p = th)
    solve_integrator(cache)
  }
  expect_identical(ntrace, 1L)
  expect_identical(cache$dpp, dpp)
  expect_null(cache$analysis)
})

test_that("reinit is specialized; the generic optimization cache path does not run", {
  prob <- ConvexOptimizationProblem(function(u, p) p[1] * u[1] + u[2], c(0.5, 0.5), c(0.5, 0),
                                    constraints = cvx_lp_cons())
  cache <- init(prob, cvx_alg)
  expect_false(has_reinit(cache))
  expect_false(exists("reinit_cache", envir = cache, inherits = FALSE))
  expect_false(inherits(cache, "OptimizationCache"))
  cache <- reinit(cache, p = c(2, 1))
  expect_equal(solve_integrator(cache)$objective, 2, tolerance = 1e-6)
})

test_that("an atom scaled by a parameter is admitted, and rejected only where invalid", {
  prob <- ConvexOptimizationProblem(function(u, p) norm(cvx_Al %*% u - cvx_bl, "2") + p[1] * norm(u, "1"),
                                    c(0, 0), 0, lb = c(-10, -10), ub = c(10, 10))
  cache <- init(prob, cvx_alg)
  for (l in c(0, 0.25, 0.5, 2, 10)) {
    cache <- reinit(cache, p = l)
    sol <- solve_integrator(cache)
    cold <- solve(remake(prob, p = l), cvx_alg)
    expect_true(successful_retcode(sol$retcode))
    expect_equal(sol$u, cold$u, tolerance = 1e-7)
    expect_equal(sol$objective, cold$objective, tolerance = 1e-7)
  }
  cache <- reinit(cache, p = 10)
  expect_equal(solve_integrator(cache)$u, c(0, 0), tolerance = 1e-6)
  expect_error(reinit(cache, p = -1), "Lowering an atom through its epigraph")
  expect_identical(cache$p, 10)
  expect_equal(solve_integrator(cache)$u, c(0, 0), tolerance = 1e-6)
})

test_that("a parameter inside an atom argument is a theta-affine cone constant", {
  prob <- ConvexOptimizationProblem(function(u, p) norm(u - p, "2"), c(0, 0), c(1, 1), constraints = cvx_c1())
  cache <- init(prob, cvx_alg)
  for (th in list(c(1, 1), c(3, -1), c(0, 0))) {
    cache <- reinit(cache, p = th)
    sol <- solve_integrator(cache)
    expect_true(successful_retcode(sol$retcode))
    expect_equal(sol$u, th + (1 - sum(th)) / 2, tolerance = 1e-6)
    expect_length(sol$dual, 1L)
  }
})

test_that("an objective coefficient may cross zero between re-solves", {
  prob <- ConvexOptimizationProblem(function(u, p) p[1] * u[1] + u[2], c(0.5, 0.5), 0, constraints = cvx_c1(),
                                    lb = c(-10, -10), ub = c(10, 10))
  truth <- function(p1) if (p1 > 1) -9 * p1 + 10 else 10 * p1 - 9
  cache <- init(prob, cvx_alg)
  for (p1 in c(0, 3, -5, 0)) {
    cache <- reinit(cache, p = p1)
    expect_equal(solve_integrator(cache)$objective, truth(p1), tolerance = 1e-6)
  }
})

