test_that("analyze reports DCP curvature and sign", {
  sa <- Symbol("cvx_sa"); sb <- Symbol("cvx_sb")
  expect_identical(analyze(exp(sa) - log(sb))$curvature, "Convex")
  expect_identical(analyze(log(sa) + sqrt(sb))$curvature, "Concave")
  expect_identical(analyze((sa - 1)^2 + 2 * abs(sb))$curvature, "Convex")
  expect_identical(analyze(3 * sa - sb)$curvature, "Affine")
  expect_identical(analyze(-(sa^2))$curvature, "Concave")
  expect_identical(analyze(exp(sa))$sign, "Positive")
  expect_identical(analyze(sa^2 + exp(sb))$sign, "Positive")
  expect_identical(analyze(sa + 1)$sign, "AnySign")
  expect_identical(analyze(exp(sa) - log(sa))$curvature, "Convex")
  expect_identical(analyze(exp(log(sa)))$curvature, "Affine")
  expect_warning(expect_identical(analyze(sa * sb)$curvature, "UnknownCurvature"), "multiple non-constant")
})

