# The probe cases (tools/convex-probe.jl)
cvx_problems <- function() list(
  lp = ConvexOptimizationProblem(function(u, p) u[1] + 2 * u[2], c(0.5, 0.5), constraints = cvx_cons()),
  soc = ConvexOptimizationProblem(function(u, p) u[3], c(0, 0, 0),
    constraints = list(ConeConstraint(function(u, p) c(u[1] - 3, u[2] - 4), MOI$Zeros(2)),
                       ConeConstraint(function(u, p) c(u[3], u[1], u[2]), MOI$SecondOrderCone(3)))),
  norm2 = ConvexOptimizationProblem(function(u, p) norm(cvx_A %*% u - cvx_b, "2"), 0),
  norm2_cons = ConvexOptimizationProblem(function(u, p) norm(u - 1, "2"), c(0.5, 0.5), constraints = cvx_cons()),
  norm1 = ConvexOptimizationProblem(function(u, p) norm(u - 1, "1"), c(0.5, 0.5), constraints = cvx_c1()),
  norminf = ConvexOptimizationProblem(function(u, p) norm(u - 1, Inf), c(0.5, 0.5), constraints = cvx_c1()),
  exp = ConvexOptimizationProblem(function(u, p) exp(u[1]) + u[2], c(0, 0),
    constraints = list(ConeConstraint(function(u, p) c(u[1] - 1, u[2]), MOI$Zeros(2)))),
  log = ConvexOptimizationProblem(function(u, p) -log(u[1]), 1,
    constraints = list(ConeConstraint(function(u, p) u[1] - 2, MOI$Zeros(1)))),
  rsoc = ConvexOptimizationProblem(function(u, p) u[1] + u[2], c(1, 1, 0),
    constraints = list(ConeConstraint(function(u, p) u[3] - 2, MOI$Zeros(1)),
                       ConeConstraint(function(u, p) c(u[1], u[2], u[3]), MOI$RotatedSecondOrderCone(3)))),
  nonpos = ConvexOptimizationProblem(function(u, p) -u[1] - u[2], c(0, 0),
    constraints = list(ConeConstraint(function(u, p) c(u[1] + 2 * u[2] - 4, 3 * u[1] + u[2] - 6), MOI$Nonpositives(2)),
                       ConeConstraint(function(u, p) c(u[1], u[2]), MOI$Nonnegatives(2)))),
  soc6 = ConvexOptimizationProblem(function(u, p) u[6], numeric(6),
    constraints = list(ConeConstraint(function(u, p) u[1:5] - 1:5, MOI$Zeros(5)),
                       ConeConstraint(function(u, p) c(u[6], u[1:5]), MOI$SecondOrderCone(6)))),
  pow = ConvexOptimizationProblem(function(u, p) -u[3], c(1, 1, 0),
    constraints = list(ConeConstraint(function(u, p) c(u[1] - 1, u[2] - 4), MOI$Zeros(2)),
                       ConeConstraint(function(u, p) c(u[1], u[2], u[3]), MOI$PowerCone(0.3)))),
  genpow = ConvexOptimizationProblem(function(u, p) -u[3] - u[4], c(1, 1, 0, 0),
    constraints = list(ConeConstraint(function(u, p) c(u[1] - 1, u[2] - 2), MOI$Zeros(2)),
                       ConeConstraint(function(u, p) u[1:4], MOI$GenPowerCone(c(0.4, 0.6), 2)))),
  psd = ConvexOptimizationProblem(function(u, p) u[1] + u[3], c(1, 0, 1),
    constraints = list(ConeConstraint(function(u, p) u[2] - 1, MOI$Zeros(1)),
                       ConeConstraint(function(u, p) u[1:3], MOI$PositiveSemidefiniteConeTriangle(2)))),
  psd3 = ConvexOptimizationProblem(function(u, p) u[1] + u[3] + u[6], c(1, 0, 1, 0, 0, 1),
    constraints = list(ConeConstraint(function(u, p) c(u[2] - 1, u[4] - 0.5, u[5] + 0.25), MOI$Zeros(3)),
                       ConeConstraint(function(u, p) u[1:6], MOI$PositiveSemidefiniteConeTriangle(3)))),
  expcon = ConvexOptimizationProblem(function(u, p) u[3], c(0, 1, 1),
    constraints = list(ConeConstraint(function(u, p) c(u[1] - 0.5, u[2] - 2), MOI$Zeros(2)),
                       ConeConstraint(function(u, p) u[1:3], MOI$ExponentialCone()))),
  lpbox = ConvexOptimizationProblem(function(u, p) u[1] - 2 * u[2], c(0, 0), constraints = cvx_c1(),
                                    lb = c(-1, -3), ub = c(2, 1.5)),
  infeas = ConvexOptimizationProblem(function(u, p) u[1], 0,
    constraints = list(ConeConstraint(function(u, p) u[1] - 1, MOI$Nonnegatives(1)),
                       ConeConstraint(function(u, p) -u[1], MOI$Nonnegatives(1)))))

cvx_sweeps <- function() list(
  lp_p = list(ConvexOptimizationProblem(function(u, p) p[1] * u[1] + u[2], c(0.5, 0.5), c(0.5, 0),
