cvx_tight <- ConvexMOI(ClarabelOptimizer(tol_gap_abs = 1e-10, tol_gap_rel = 1e-10, tol_feas = 1e-10, tol_ktratio = 1e-10))
cvx_tight12 <- ConvexMOI(ClarabelOptimizer(tol_gap_abs = 1e-12, tol_gap_rel = 1e-12, tol_feas = 1e-12, tol_ktratio = 1e-12))
cvx_QA <- matrix(c(1, 0, 1, 2, 0, 1, 1, 0, 2, 1, 0, 1), 4, 3)
cvx_QB <- c(1, 2, 3, 4)
cvx_P2 <- matrix(c(2, 0.5, 0.5, 1), 2)
cvx_Xd <- function(u) matrix(c(u[1], 0, 0, 1 - u[1]), 2)
cvx_cz <- function(idx, vals) ConeConstraint(function(u, p) u[idx] - vals, MOI$Zeros(length(idx)))
cvx_set <- function(k, set) ConeConstraint(function(u, p) u[seq_len(k)], set)
cvx_Mf <- c(2, 0.5, 1, 0.5, 1, 3)
cvx_nocd <- ConvexMOI(ClarabelOptimizer(chordal_decomposition_complete_dual = FALSE))
# bridged sets whose PSD cone is decomposed (Julia fails on these by default)
cvx_psd_bridged <- c("normspec", "logdet_sq", "rootdet_tri", "rootdet_sq")
cvx_bandsq <- function(u, n) {
  X <- matrix(list(0), n, n)
  for (j in seq_len(n)) for (i in seq_len(n))
    X[[i, j]] <- if (i == j) u[i] else if (abs(i - j) == 1) u[n + min(i, j)] else 0
  as.vector(X)
}
cvx_arrowsq <- function(u, n) {
  X <- matrix(list(0), n, n)
  for (j in seq_len(n)) for (i in seq_len(n))
    X[[i, j]] <- if (i == j) u[i] else if (i == 1 || j == 1) u[n + max(i, j) - 1] else 0
  as.vector(X)
}
cvx_chordal <- function(f, n) {
  # the cases are built in a loop, so the matrix builder is fixed now
  force(f)
  ConvexOptimizationProblem(function(u, p) sum(u[seq_len(n)]), c(rep(1, n), rep(0, n - 1)),
    constraints = list(ConeConstraint(function(u, p) u[n + seq_len(n - 1)] - 1, MOI$Zeros(n - 1)),
                       ConeConstraint(function(u, p) do.call(c, f(u, n)), MOI$PositiveSemidefiniteConeSquare(n))))
}

