test_that("the probe cases match ConvexOptimization.jl and Clarabel.jl", {
  pr <- c(cvx_problems(), cvx_problems_014())
  for (nm in names(pr)) {
    if (is.null(cvx_ref[[nm]])) next
    cvx_check(nm, cvx_run(pr[[nm]], cvx_alg_for(nm)), cvx_ref[[nm]], cvx_ref)
  }
  sw <- c(cvx_sweeps(), cvx_sweeps_014())
  for (nm in names(sw)) {
    cache <- init(sw[[nm]][[1]], cvx_alg_for(nm))
    for (k in seq_along(sw[[nm]][[2]])) {
      key <- paste0(nm, "_", k)
      cache <- reinit(cache, p = sw[[nm]][[2]][[k]])
      got <- tryCatch(suppressWarnings(cvx_record(cache, solve_integrator(cache))),
                      error = function(e) list(retcode = "ERROR", error = conditionMessage(e)))
      if (!is.null(cvx_ref[[key]])) cvx_check(key, got, cvx_ref[[key]], cvx_ref)
    }
  }
})

